-- Reconstructed baseline matching Supabase inspection (no business data).
-- Never run against Supabase; isolated tests only.
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE public."MakeupBookingSystem"(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.admin_users(id bigserial PRIMARY KEY, username varchar(50) NOT NULL, password_hash text NOT NULL, role varchar(20) NOT NULL DEFAULT 'Admin', is_active boolean NOT NULL DEFAULT true, CONSTRAINT admin_users_username_key UNIQUE(username));
CREATE TABLE public.makeup_artists(id bigserial PRIMARY KEY, full_name varchar(150) NOT NULL, phone varchar(20), is_active boolean NOT NULL DEFAULT true);
CREATE TABLE public.artist_availability(id bigserial PRIMARY KEY, artist_id bigint NOT NULL REFERENCES public.makeup_artists(id), weekday int NOT NULL, start_time time NOT NULL, end_time time NOT NULL, CONSTRAINT artist_availability_check CHECK (end_time > start_time), CONSTRAINT artist_availability_weekday_check CHECK (weekday >= 0 AND weekday <= 6));
CREATE TABLE public.blocked_slots(id bigserial PRIMARY KEY, artist_id bigint NOT NULL REFERENCES public.makeup_artists(id), start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, reason text, CONSTRAINT blocked_slots_check CHECK (end_at > start_at));
CREATE TABLE public.customers(id bigserial PRIMARY KEY, full_name varchar(150) NOT NULL, phone varchar(20) NOT NULL, email varchar(150), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.services(id bigserial PRIMARY KEY, name varchar(100) NOT NULL, description text, price numeric(10,2) NOT NULL, duration_minutes int NOT NULL, is_active boolean NOT NULL DEFAULT true, CONSTRAINT services_duration_minutes_check CHECK (duration_minutes > 0), CONSTRAINT services_price_check CHECK (price >= 0::numeric));
CREATE TABLE public.reservations(id bigserial PRIMARY KEY, reference varchar(30) NOT NULL, customer_id bigint NOT NULL REFERENCES public.customers(id), service_id bigint NOT NULL REFERENCES public.services(id), artist_id bigint NOT NULL REFERENCES public.makeup_artists(id), start_at timestamptz NOT NULL, end_at timestamptz NOT NULL, location text, notes text, total_price numeric(10,2) NOT NULL, status varchar(20) NOT NULL DEFAULT 'Pending', created_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT reservations_reference_key UNIQUE (reference), CONSTRAINT reservations_check CHECK (end_at > start_at), CONSTRAINT reservations_status_check CHECK (status::text = ANY (ARRAY['Pending','Confirmed','InProgress','Completed','Cancelled','Rejected','NoShow'])), CONSTRAINT reservations_total_price_check CHECK (total_price >= 0::numeric), CONSTRAINT no_artist_overlap EXCLUDE USING gist (artist_id WITH =, tstzrange(start_at, end_at, '[)') WITH &&) WHERE (status::text = ANY (ARRAY['Pending','Confirmed','InProgress'])));
CREATE INDEX idx_reservations_artist_time ON public.reservations USING btree (artist_id, start_at, end_at);
CREATE INDEX idx_reservations_status ON public.reservations USING btree (status);
CREATE TABLE public.payments(id bigserial PRIMARY KEY, reservation_id bigint NOT NULL REFERENCES public.reservations(id), amount numeric(10,2) NOT NULL, method varchar(30) NOT NULL, status varchar(20) NOT NULL DEFAULT 'Pending', paid_at timestamptz, CONSTRAINT payments_amount_check CHECK (amount > 0::numeric), CONSTRAINT payments_status_check CHECK (status::text = ANY (ARRAY['Pending','Paid','Failed','Refunded'])));
CREATE TABLE public.reservation_history(id bigserial PRIMARY KEY, reservation_id bigint NOT NULL REFERENCES public.reservations(id), changed_by varchar(100) NOT NULL, old_status varchar(20), new_status varchar(20) NOT NULL, changed_at timestamptz NOT NULL DEFAULT now());
